head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/mgt.js");
scwin.vScrenID = 'ULDMGT10000.xml';
scwin.toDay = '';
scwin.clientnow = new Date();

/* 오늘 날짜를 구한다 */
scwin.curYear = scwin.clientnow.getYear();
scwin.curMonth = (scwin.clientnow.getMonth()) + 1;
scwin.curDay = scwin.clientnow.getDate();
if (scwin.curMonth <= 9) {
    scwin.curMonth = "0" + scwin.curMonth;
}
if (scwin.curDay <= 9) {
    scwin.curDay = "0" + scwin.curDay;
}
scwin.txb_date = scwin.curYear + "" + scwin.curMonth + "" + scwin.curDay;
scwin.toDay = scwin.txb_date;


// 현시각(시분) 20210528
scwin.curHH = scwin.clientnow.getHours();
scwin.curMM = scwin.clientnow.getMinutes();
if (scwin.curHH <= 9) {
    scwin.curHH = "0" + scwin.curHH;
}
if (scwin.curMM <= 9) {
    scwin.curMM = "0" + scwin.curMM;
}
scwin.vNowHHMM = scwin.curHH + "" + scwin.curMM;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
//alert(vNowHHMM);

scwin.fn_list_sync = function() {
    scwin.txb_date = tmbDate.getValue();
    var url = "/bzchklist.do?method=searchBzChkList&inputMessageId=bzchklist&outputMessageId=bzchklist&BAS_DD=" + scwin.txb_date + "&CHK_BZ_TP_CD=00" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet.DataID = encodeURI(url);
    MxDataSet.reset();
    //ShowWin(MxGrid_1); 

};
scwin.fn_list_sub = function(sval) {
    var url = "/bzchklist.do?method=searchBzChkList&inputMessageId=bzchklist&outputMessageId=bzchklist&BAS_DD=" + scwin.txb_date + "&CHK_BZ_TP_CD=" + sval;
    MxDataSet_select.DataID = encodeURI(url);
    MxDataSet_select.reset();
    //ShowWin(MxGrid_1); 

};
scwin.fn_list_sync2 = function() {
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet.reset();
    MxDataSet_select.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet_select.reset();
    MxDataSet_insert.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet_insert.reset();
    var url = "/bzchklist.do?method=searchBzChkList&inputMessageId=bzchklist&outputMessageId=bzchklist&BAS_DD=" + scwin.txb_date + "&CHK_BZ_TP_CD=00";
    MxDataSet.DataID = encodeURI(url);
    MxDataSet.reset();
    //ShowWin(MxGrid_1); 

};
scwin.fn_save = function() {
    //MxDataSet_insert.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet_insert.reset();
    if (!scwin.fn_cntDatasetRowCheck(MxDataSet)) {
        $c.win.alert('체크사항이 없습니다');
        return;
    }
    var lastch = "Y"; //최종업무확인
    var unitCl = 0;
    for (i = 1; i <= MxDataSet.getTotalRow(); i++) {
        if (MxDataSet.getCellData(i, "CHK_FLAG") == 1) {
            unitCl = i;
        }
    }
    if (unitCl != 0) {
        MxDataSet.insertRow();
        //alert("단위업무마감을 시작합니다.");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "BAS_DD", MxDataSet.getCellData(unitCl, "BAS_DD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CHK_BZ_TP_CD", MxDataSet.getCellData(unitCl, "CHK_BZ_TP_CD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "UNIT_BZ_CLS_DDTM", "99991231000000");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CLS_TRANSTR_EMP_NO", js_emp_no);
    }
    for (k = 1; k <= MxDataSet.getTotalRow(); k++) {
        if (MxDataSet.getCellData(k, "CHK_BZ_TP_CD") == '40' && MxDataSet.getCellData(k, "UNIT_BZ_CLS_DDTM") == "99991231000000") {
            lastch = "N";
            break;
        }
    }
    if (lastch == "Y") {
        MxDataSet.insertRow();
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "BAS_DD", MxDataSet.getCellData(1, "BAS_DD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CHK_BZ_TP_CD", "40");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "UNIT_BZ_CLS_DDTM", "99991231000000");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CLS_TRANSTR_EMP_NO", js_emp_no);
    }
    /*
					MxDataSet_insert.AddRow();
MxDataSet_insert.setNameValue(1, "BAS_DD","20080516") ;
MxDataSet_insert.setNameValue(1, "CHK_BZ_TP_CD","31") ;
MxDataSet_insert.setNameValue(1, "UNIT_BZ_STRT_DDTM",MxDataSet_insert.NameValue(1, "UNIT_BZ_STRT_DDTM") =) ;
MxDataSet_insert.setNameValue(1, "UNIT_BZ_CLS_DDTM",MxDataSet_insert.NameValue(1, "UNIT_BZ_CLS_DDTM") =) ;
MxDataSet_insert.setNameValue(1, "CLS_TRANSTR_EMP_NO","010271") ;
		*/
    //alert(MxDataSet_insert.Text);
    //alert("단위업무의 재시작을 시작합니다\n최종업무가 마감된 경우 최종업무는 개시됩니다");
    MxLogicalTr_save.Action = "/bzchklist.do?method=saveBzChkList&inputMessageId=bzchklist";
    MxLogicalTr_save.KeyName = "toinb_dataid4";
    MxLogicalTr_save.KeyValue = "JSP(I:pInput=MxDataSet)";
    MxLogicalTr_save.Post();
};
scwin.fn_save2 = function() {
    $c.win.alert("금감원 제출, 코스콤공시전송을 제외한 시작되지 않은 모든 업무를 수동시작합니다.");
    for (i = 1; i <= MxDataSet.getTotalRow(); i++) {
        if (MxDataSet.getCellData(i, "BAS_DD") == "" && MxDataSet.getCellData(i, "CHK_BZ_TP_CD").substring(0, 1) != '2') {
            if (MxDataSet.getCellData(i, "CHK_BZ_TP_CD") != '51') {
                MxDataSet.setCellData(i, "BAS_DD", scwin.txb_date);
            }
        }
    }

    //alert(MxDataSet.Text);
    MxLogicalTr_save.Action = "/bzchklist.do?method=saveBzChkList&inputMessageId=bzchklist";
    MxLogicalTr_save.KeyName = "toinb_dataid4";
    MxLogicalTr_save.KeyValue = "JSP(I:pInput=MxDataSet)";
    MxLogicalTr_save.Post();
};
scwin.fn_chk = function(sval) {
    if (MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '31' && //유가 공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '32' && //코스닥 공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '33' && //코스닥시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '34' && //주식시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '35' && //ETF시장팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '36' && //예방감시팀(코스닥)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '37' && //예방감시팀(유가)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '39' && //시장감시3팀(ELW)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '38' && //채권상장공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3A' && //코넥스상장공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3B' && //코넥스시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3C' && //예방감시팀(코넥스)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3E' && //예방감시팀(배출권)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3D' && //ETN시장팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") != '3F') {
        $c.win.alert("재시작 대상업무가 아닙니다.");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    if (MxDataSet.getCellData(sval, "BAS_DD") == '') {
        $c.win.alert("업무가 시작되지 않았습니다");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    if (MxDataSet.getCellData(sval, "UNIT_BZ_CLS_DDTM") == '99991231000000') {
        $c.win.alert("업무가 종료되지 않았습니다.");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    for (i = 1; i <= MxDataSet.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (MxDataSet.getCellData(i, "CHK_FLAG") == 1 && i != sval) /*ORG SRC: if (MxDataSet.NameValue(i, "CHK_FLAG") == 1 && i != sval) MxDataSet.NameValue(i, "CHK_FLAG") = 0;*/ X = 0;
    }
    MxDataSet.getCellData(sval, "CHK_FLAG") == 1;
};
scwin.fn_cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        //alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) return false;

    else return true;
};
scwin.notEndDocLst = async function() {
    var url = "/jobmonitor/ULDMGT10005.gfm?date=" + tmbDate.getValue();
    var left = screen.width / 2 - document.body.offsetWidth / 2;
    var right = screen.height / 2 - document.body.offsetHeight / 2;
    await $c.frame.CreateDialogFrame("virWinNotEndDocLst", url, "미처리 공시 리스트(" + tmbDate.getValue() + ")", left, right, 865, 315, "tool");
};
scwin.MxGrid_1_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
    //CloseWin(rowcount, MxGrid_1); 

};
scwin.gform_onload = function() {
    tmbDate.setValue(scwin.txb_date);
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet.reset();
    MxDataSet_insert.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet_insert.reset();
    MxDataSet_select.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=bzchklist";
    MxDataSet_select.reset();
    $c.cm.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

    //미승인건 조회 버튼은 18시 이후부터 보이도록 수정 20210528
    if (scwin.vNowHHMM > '1800') {
        showObj(image_3, true);
    } else {
        showObj(image_3, false);
    }
    scwin.fn_list_sync();
    //toDaySet(txb_date);

};
scwin.btn_sys_search_onclick = function() {
    scwin.fn_list_sync(); //alert();

};
scwin.image_1_onclick = function() {
    if (scwin.toDay == scwin.txb_date) {
        scwin.fn_save();
    } else {
        $c.win.alert("과거일은 조회만 가능합니다.");
    }
};
scwin.MxLogicalTr_save_OnFail = function() {
    scwin.fn_list_sync();
};
scwin.MxLogicalTr_save_OnSuccess = function() {
    scwin.fn_list_sync();
};
scwin.MxGrid_1_OnCheckClick = function(col, colid, bCheck) {
    if (bCheck != 0) {
        scwin.fn_chk(col);
        //alert('MxGrid_1.OnCheckClick('+col+','+ colid+','+ bCheck+')');

    }
};
scwin.image_2_onclick = function() {
    if (scwin.toDay == scwin.txb_date) {
        if (confirm('really?')) scwin.fn_save2();
    } else {
        $c.win.alert("과거일은 조회만 가능합니다.");
    }
};
scwin.MxGrid_1_OnClick = function(row, colid) {
    scwin.fn_list_sub(MxDataSet.getCellData(row, "CHK_BZ_TP_CD"));
};
scwin.btn_cal_onclick = function() {
    popUpCalendar(txb_date_bg, 'tmbDate', 'yyyymmdd'); //alert('image_2.onclick');		

};
scwin.image_3_onclick = function() {
    scwin.notEndDocLst();
};
